-- KanVibe SQLite schema as created by the TS app at commit ba3c5093 (17 migrations).
-- Generated by letting the Electron app create an empty DB in an isolated KANVIBE_APP_DATA_DIR,
-- then: sqlite3 kanvibe.db .schema  +  the migrations rows. Do not edit by hand.
CREATE TABLE "migrations" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "timestamp" bigint NOT NULL, "name" varchar NOT NULL);
CREATE TABLE "kanban_tasks" (
        "id" TEXT PRIMARY KEY NOT NULL,
        "title" TEXT NOT NULL,
        "description" TEXT,
        "status" TEXT NOT NULL DEFAULT 'todo',
        "branch_name" TEXT,
        "worktree_path" TEXT,
        "session_type" TEXT,
        "session_name" TEXT,
        "ssh_host" TEXT,
        "agent_type" TEXT,
        "project_id" TEXT,
        "base_branch" TEXT,
        "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "updated_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "pr_url" TEXT, "priority" TEXT DEFAULT NULL,
        FOREIGN KEY ("project_id") REFERENCES "projects"("id") ON DELETE SET NULL
      );
CREATE INDEX "idx_kanban_tasks_project_branch"
        ON kanban_tasks(project_id, branch_name)
    ;
CREATE TABLE "pane_layout_configs" (
        "id" TEXT PRIMARY KEY NOT NULL,
        "layout_type" TEXT NOT NULL,
        "panes" TEXT NOT NULL,
        "project_id" TEXT UNIQUE,
        "is_global" INTEGER NOT NULL DEFAULT 0,
        "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "updated_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY ("project_id") REFERENCES "projects"("id") ON DELETE CASCADE
      );
CREATE TABLE "app_settings" (
        "id" TEXT PRIMARY KEY NOT NULL,
        "key" TEXT NOT NULL UNIQUE,
        "value" TEXT NOT NULL,
        "created_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "updated_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
      );
CREATE TABLE "projects" (
      id TEXT PRIMARY KEY NOT NULL,
      name TEXT NOT NULL,
      repo_path TEXT NOT NULL,
      default_branch TEXT NOT NULL DEFAULT 'main',
      ssh_host TEXT,
      is_worktree INTEGER NOT NULL DEFAULT 0,
      color TEXT DEFAULT NULL,
      icon_data_url TEXT DEFAULT NULL,
      created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
    );
CREATE INDEX "idx_kanban_tasks_status_order"
        ON kanban_tasks(status, updated_at)
    ;
CREATE TABLE "task_diff_stats" (
        "task_id" TEXT PRIMARY KEY NOT NULL,
        "file_count" INTEGER NOT NULL DEFAULT 0,
        "additions" INTEGER NOT NULL DEFAULT 0,
        "deletions" INTEGER NOT NULL DEFAULT 0,
        "updated_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY ("task_id") REFERENCES "kanban_tasks"("id") ON DELETE CASCADE
      );

